bool CollectCityRecord(CvCity& city, PlayerTypes capturingPlayer, CityRecord& out)
{
    bool indirectFireAllowed = false;

    // Stable city identifier.
    out.id = static_cast<i32>(city.GetID());
    // Portable city plot index.
    out.plotIndex = static_cast<i32>(city.plot()->GetPlotIndex());
    // Maximum hit points.
    out.maxHitPoints = static_cast<i32>(city.GetMaxHitPoints());
    // Current damage.
    out.damage = static_cast<i32>(city.getDamage());
    // Normal, non-range-strike strength.
    out.strengthValue = static_cast<i32>(city.getStrengthValue(false));
    // The mutable indirect-fire output is captured below.
    out.bombardRange = static_cast<i32>(city.getBombardRange(indirectFireAllowed));
    // Stable garrison unit identifier or -1.
    out.garrisonUnitId = static_cast<i32>(city.GetGarrisonedUnit() ? city.GetGarrisonedUnit()->GetID() : -1);
    // Damage taken last turn.
    out.damageTakenLastTurn = static_cast<i32>(city.getDamageTakenLastTurn());
    // Requires the operational player and is non-const.
    out.economicValue = static_cast<i32>(city.getEconomicValue(capturingPlayer));
    // Owner player.
    out.owner = static_cast<i8>(city.getOwner());
    // Owner team.
    out.team = static_cast<i8>(city.getTeam());
    // Can make a ranged strike.
    out.canRangeStrike = (city.canRangeStrike()) ? 1 : 0;
    // Set by getBombardRange(bool&).
    out.indirectFireAllowed = (indirectFireAllowed) ? 1 : 0;
    // Land and water blockade state.
    out.blockadedWaterAndLand = (city.IsBlockadedWaterAndLand()) ? 1 : 0;
    // Native default carefulness.
    out.inDangerOfFalling = (city.isInDangerOfFalling()) ? 1 : 0;
    // Native default minimum water size.
    out.coastal = (city.isCoastal()) ? 1 : 0;
    // Original capital flag.
    out.originalCapital = (city.IsOriginalCapital()) ? 1 : 0;
    // Original owner.
    out.originalOwner = static_cast<i8>(city.getOriginalOwner());
    return true;
}

