    out.canCrossMountain = (player.CanCrossMountain()) ? 1 : 0;
    // Ice crossing ability.
    out.canCrossIce = (player.CanCrossIce()) ? 1 : 0;
    // Player team.
    out.team = static_cast<i8>(player.getTeam());
